(function(){
const KEY=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seeds=[{id:'nWey1DBAchM',title:'a-ha • Stay On These Roads'},{id:'cqZJysZCS_k',title:'Música adicionada recentemente'}];
let entries=[];let removed=[];try{entries=JSON.parse(localStorage.getItem('musicsense_favorites')||'[]');removed=JSON.parse(localStorage.getItem('musicsense_removed')||'[]')}catch{}
function add(id,title){if(!id)return;removed=removed.filter(x=>x!==id);localStorage.setItem('musicsense_removed',JSON.stringify(removed));entries=[{id,title:title||'Música do YouTube'},...entries.filter(x=>x.id!==id)].slice(0,30);localStorage.setItem('musicsense_favorites',JSON.stringify(entries));drawGrid()}
function drawGrid(){const all=[...entries,...seeds.filter(s=>!entries.some(x=>x.id===s.id))].filter(x=>!removed.includes(x.id));$('musicGrid').replaceChildren();all.forEach(x=>{const card=document.createElement('div');card.className='musicitem';card.tabIndex=0;card.title='Duplo clique para carregar e analisar';const img=document.createElement('img');img.src='https://i.ytimg.com/vi/'+x.id+'/hqdefault.jpg';img.alt=x.title;img.loading='lazy';const meta=document.createElement('div');meta.className='meta';const title=document.createElement('strong');title.textContent=x.title;const sub=document.createElement('small');sub.textContent='Duplo clique para ouvir e traduzir';meta.append(title,sub);card.append(img,meta);const del=document.createElement('button');del.type='button';del.className='music-remove';del.textContent='X';del.title='Remover da colecao';del.setAttribute('aria-label','Remover '+x.title);del.addEventListener('click',e=>{e.stopPropagation();if(!confirm('Remover esta musica da colecao?'))return;removed.push(x.id);entries=entries.filter(z=>z.id!==x.id);localStorage.setItem('musicsense_removed',JSON.stringify(removed));localStorage.setItem('musicsense_favorites',JSON.stringify(entries));drawGrid()});card.append(del);const run=()=>{$('url').value='https://www.youtube.com/watch?v='+x.id;youtubeLoad();$('ytAnalyze').click();window.scrollTo({top:0,behavior:'smooth'})};card.addEventListener('dblclick',run);card.addEventListener('keydown',e=>{if(e.key==='Enter')run()});$('musicGrid').append(card)})}
window.MusicSenseLibrary={add};drawGrid();
$('saveFavorite').onclick=()=>{if(!currentVideoId)return setStatus('Abra um link do YouTube para favoritar.');add(currentVideoId,currentTitle);setStatus('Música salva na sua coleção deste navegador.')};
$('printLyrics').onclick=()=>{if(!analyzed?.segments?.length)return setStatus('Analise uma música antes de gerar o PDF.');$('pdfDialog').showModal()};
$('pdfPreview').onclick=()=>{
if(!analyzed?.segments?.length)return;
const include=$('pdfContent').value==='both';
const title=currentTitle||lastFile?.name||'Minha música';
const date=new Date().toLocaleDateString('pt-BR');
const duration=activeMedia?.duration||analyzed.duration||0;
const durationText=duration?Math.floor(duration/60)+':'+String(Math.floor(duration%60)).padStart(2,'0'):'Não informado';
let img=currentVideoId?'https://i.ytimg.com/vi/'+currentVideoId+'/hqdefault.jpg':null;
if(!img&&activeMedia===$('video')&&activeMedia.videoWidth){try{const canvas=document.createElement('canvas');canvas.width=640;canvas.height=360;canvas.getContext('2d').drawImage(activeMedia,0,0,640,360);img=canvas.toDataURL('image/jpeg',.8)}catch{}}

const rows=analyzed.segments.map(s=>'<div class="verse"><div class="english">'+esc(s.original)+'</div>'+(include?'<div class="portuguese">'+esc(s.translation||'Tradução indisponível')+'</div>':'')+'</div>').join('');
const html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>'+esc(title)+' | MusicSense AI</title><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#20233b;margin:0;background:#f4f3f8}.page{max-width:210mm;margin:auto;background:white;padding:22px 30px;min-height:100vh}.brand{font-size:12px;color:#7455b8;font-weight:bold;letter-spacing:2px}.hero{display:flex;gap:20px;align-items:center;padding:22px 0;border-bottom:2px solid #a98aff}.hero img{width:170px;aspect-ratio:16/9;object-fit:cover;border-radius:9px}h1{font-size:26px;line-height:1.2;margin:0 0 10px}.meta{font-size:11px;color:#697087;line-height:1.7}.verse{padding:7px 0;border-bottom:1px solid #ecebf1;break-inside:avoid}.english{font-size:12px;font-weight:700;line-height:1.5}.portuguese{font-size:11px;color:#75609a;margin-top:4px;line-height:1.5}.chordline{display:block;line-height:1.4!important;padding-top:5px}.chordpair{display:inline-flex;flex-direction:column;vertical-align:bottom;white-space:pre}.chordname{font-family:Arial,sans-serif;font-size:11px;color:#6545ad;font-weight:800;line-height:1.1}.lyricpart{white-space:pre}.plain{white-space:pre-wrap}.chords{font-family:monospace;color:#9c6a1c;white-space:pre-wrap;font-size:13px;font-weight:bold;margin-bottom:5px}.foot{margin-top:24px;font-size:10px;color:#7b8194}.toolbar{position:sticky;top:0;background:#1a1b30;color:white;padding:12px;display:flex;gap:10px;justify-content:center}.toolbar button{background:#ae8bff;border:0;padding:10px 18px;border-radius:8px;cursor:pointer;font-weight:bold}@media print{body{background:white}.page{padding:0;min-height:0;max-width:none}.toolbar{display:none}.verses{column-count:2;column-gap:10mm;column-rule:1px solid #ecebf1}.verse{break-inside:avoid;page-break-inside:avoid}.hero{padding:8px 0 12px;margin-bottom:12px}.hero img{width:110px}h1{font-size:19px}.brand{font-size:10px}}@media screen{.verses{column-count:2;column-gap:24px}}</style></head><body><div class="toolbar"><span>Pré-visualização do documento</span><button onclick="window.print()">Imprimir / Salvar PDF</button><button onclick="window.close()">Fechar</button></div><div class="page"><div class="brand">♫ MUSICSENSE AI • SONGBOOK</div><div class="hero">'+(img?'<img src="'+img+'" alt="Capa do vídeo">':'')+'<div><h1>'+esc(title)+'</h1><div class="meta">Fonte: '+esc(currentVideoId?'YouTube':'Arquivo local')+(analyzed.artist?'<br>Artista/canal: '+esc(analyzed.artist):'')+'<br>Idioma original: '+esc(analyzed.language||'não identificado')+' • Duração: '+esc(durationText)+'<br>Gerado em: '+date+' • '+analyzed.segments.length+' trechos'+'</div></div></div>'+'<div class=verses>'+rows+'</div><div class="foot">Transcrição e tradução automáticas, sujeitas a erros. Revise antes de compartilhar. </div></div></body></html>';
const w=window.open('','_blank');if(!w){setStatus('Permita pop-ups para visualizar o PDF.');return}w.document.open();w.document.write(html);w.document.close();$('pdfDialog').close()};
$('exportVideo').onclick=()=>window.MusicSenseExport?.start?.('audio');
$('exportOriginalVideo').onclick=()=>window.MusicSenseExport?.start?.('video');
})();